<script setup>
import AppShell from'../../Layouts/AppShell.vue';import StateCard from'../../Components/StateCard.vue';import{Head,router,useForm}from'@inertiajs/vue3';import{computed,onBeforeUnmount,onMounted,ref,watch}from'vue';
const props=defineProps({event:Object,purpose:String,consentVersion:String,minorEnabled:Boolean,consent:Object,subject:Object,deletion:Object});
const accepted=ref(false),adult=ref(false),file=ref(null),preview=ref(null),input=ref(null),timer=ref();const consentForm=useForm({accepted:true,is_minor:false,privacy_notice_version:props.consentVersion}),selfieForm=useForm({consent_uuid:props.consent?.uuid,selfie:null});
const activeConsent=computed(()=>props.consent?.state==='granted'&&props.consent?.privacy_notice_version===props.consentVersion);const processing=computed(()=>['queued','processing'].includes(props.subject?.state));
function clearFile(){if(preview.value)URL.revokeObjectURL(preview.value);preview.value=null;file.value=null;selfieForm.selfie=null;if(input.value)input.value.value=''}
function choose(e){clearFile();const next=e.target.files?.[0];if(!next)return;file.value=next;selfieForm.selfie=next;preview.value=URL.createObjectURL(next)}
function grant(){consentForm.post(`/groups/${props.event.id}/biometric-consents`,{onSuccess:()=>router.reload({only:['consent']})})}
function submit(){selfieForm.consent_uuid=props.consent.uuid;selfieForm.post(`/groups/${props.event.id}/face-searches`,{forceFormData:true,onSuccess:()=>{clearFile();router.reload({only:['subject']})}})}
function cancel(){if(props.subject&&confirm('Cancel this search? Your temporary selfie will be deleted.'))router.post(`/face-searches/${props.subject.uuid}/cancel`,{}, {onSuccess:()=>router.reload()})}
function withdraw(){if(confirm('Withdraw biometric consent? Personalized results may be removed and your temporary selfie will be deleted.'))router.delete(`/biometric-consents/${props.consent.uuid}`,{onSuccess:()=>router.reload()})}
function erase(){if(confirm('Request complete biometric deletion for this event? Personalized results and associated biometric records will be removed.'))router.post('/biometric-deletion-requests',{scope:'event',group_id:props.event.id},{onSuccess:()=>router.reload()})}
onMounted(()=>{timer.value=setInterval(()=>{if(processing.value||['queued','processing'].includes(props.deletion?.state))router.reload({only:['subject','deletion'],preserveScroll:true})},2500)});onBeforeUnmount(()=>{clearInterval(timer.value);clearFile()});watch(()=>props.subject?.state,s=>{if(s==='completed')clearFile()});
</script>
<template><AppShell><Head title="Find My Photos"/><div class="mx-auto max-w-4xl"><p class="eyebrow">Consent-led discovery</p><h1 class="mt-2 font-display text-3xl font-bold">Find My Photos · {{event.name}}</h1><p class="mt-3 max-w-2xl text-sm leading-6 text-black/55">Similarity matching can be incorrect. You remain in control and can reject individual results, withdraw consent, or request deletion.</p><section v-if="!activeConsent" class="panel mt-8 p-6 md:p-8"><h2 class="font-display text-xl font-bold">Your biometric choice</h2><p class="mt-4 rounded-xl bg-indigo/5 p-4 text-sm leading-6"><b>Purpose:</b> {{purpose}}</p><p class="mt-3 text-xs text-black/45">Consent notice version {{consentVersion}}. This consent is separate from joining the event.</p><label class="mt-6 flex gap-3 text-sm"><input v-model="accepted" type="checkbox">I explicitly consent to this biometric purpose.</label><label class="mt-4 flex gap-3 text-sm"><input v-model="adult" type="checkbox">I confirm I am not a minor.</label><div class="mt-6 flex flex-wrap gap-3"><button class="btn-primary" :disabled="!accepted||(!minorEnabled&&!adult)||consentForm.processing" @click="grant">Grant consent</button><a :href="`/groups/${event.id}`" class="btn-muted">Continue without My Photos</a></div><p v-if="!minorEnabled" class="mt-4 text-xs text-coral">Biometric processing for minors is disabled.</p></section><section v-else class="mt-8 space-y-6"><div v-if="!subject||['failed','cancelled'].includes(subject.state)" class="panel p-6 md:p-8"><h2 class="font-display text-xl font-bold">Submit a private selfie</h2><p class="mt-2 text-sm text-black/50">Use one clearly visible face. The temporary selfie is deleted after processing, failure or cancellation.</p><input ref="input" class="mt-5 block w-full text-sm" type="file" accept="image/jpeg,image/png,image/webp" capture="user" @change="choose"><div v-if="preview" class="mt-5 flex items-center gap-4"><img :src="preview" alt="Temporary selfie preview" class="h-28 w-28 rounded-xl object-cover"><button class="btn-muted" @click="clearFile">Remove</button></div><button class="btn-primary mt-5" :disabled="!file||selfieForm.processing" @click="submit">{{selfieForm.processing?'Uploading privately…':'Submit selfie'}}</button></div><StateCard v-if="processing" title="Finding your moments" message="Your search is running in the durable processing queue."><button class="btn-muted mt-5" @click="cancel">Cancel and delete selfie</button></StateCard><StateCard v-else-if="subject?.outcome==='no_face'" tone="error" title="No face detected" message="Retake your selfie in even light with your face clearly visible."/><StateCard v-else-if="subject?.outcome==='multiple_faces'" tone="error" title="More than one face detected" message="Please submit a selfie containing only you."/><StateCard v-else-if="subject?.state==='failed'" tone="error" title="Search failed safely" message="No result was made available and your temporary selfie was deleted."/><div v-else-if="subject?.state==='completed'" class="panel p-6"><h2 class="font-display text-xl font-bold">Search completed</h2><a :href="`/face-searches/${subject.uuid}/results`" class="btn-primary mt-4">View My Photos</a></div><div class="panel p-6"><h2 class="font-display text-lg font-bold">Privacy controls</h2><p class="mt-2 text-sm text-black/50">Withdrawal stops future use. A deletion request removes event-specific biometric records through the audited deletion queue.</p><div class="mt-5 flex flex-wrap gap-3"><button class="btn-muted" @click="withdraw">Withdraw consent</button><button class="btn bg-coral text-white" @click="erase">Request complete deletion</button></div><p v-if="deletion" class="mt-4 text-sm font-semibold">Deletion status: {{deletion.state}}</p></div></section></div></AppShell></template>
